function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#4a1018', R='#e03050', RLt='#ff6a80', RDk='#a01830';
  // two lobes
  px(12,16,18,16,O); px(34,16,18,16,O);
  px(13,17,16,14,R); px(35,17,16,14,R);
  // point
  px(16,28,32,20,O); px(17,28,30,18,R);
  for (let i=0;i<12;i++) px(18+i,46+i,28-i*2,1,R);
  px(18,18,8,6,RLt); px(40,18,6,4,RLt);
  px(28,36,8,6,RDk);

}
